#include "boot_ui.h"
#include "colors.h"

// boot_images.c, generated by scripts/gen_boot_images.py from assets/boot/.
extern "C" const lv_img_dsc_t boot_img_toyota;
extern "C" const lv_img_dsc_t boot_img_gr_yaris;

// Timeline, in ms from build(). Two beats -- the Toyota logo, then the
// GR Yaris one -- each a fade in / hold / fade out. ~4 s in all: long enough
// to read as a deliberate start-up, short enough that it is over before the
// car is in gear.
//
// Fades go through img_opa on the individual images, never opa on the
// overlay itself: whole-object opacity makes LVGL render the subtree into a
// separate layer first, which is exactly the kind of cost the full-refresh
// flush on this panel can't afford (see display_driver.cpp). The images are
// opaque RGB565, pre-flattened onto kBg, so a fade is one blend per pixel.
namespace BootUi {

namespace {
constexpr uint32_t kFirstInStart = 150;
constexpr uint32_t kFirstInEnd = 650;
constexpr uint32_t kFirstOutStart = 1700;
constexpr uint32_t kFirstOutEnd = 2050;
constexpr uint32_t kSecondInStart = 2150;
constexpr uint32_t kSecondInEnd = 2650;
constexpr uint32_t kSecondOutStart = 3650;
constexpr uint32_t kSecondOutEnd = 4000;

lv_obj_t *g_overlay = nullptr;
lv_obj_t *g_first = nullptr;
lv_obj_t *g_second = nullptr;
lv_timer_t *g_timer = nullptr;
uint32_t g_startMs = 0;

// 0..1 progress of t through [a, b], eased (cubic out).
float ease(uint32_t t, uint32_t a, uint32_t b) {
    if (t <= a) return 0.0f;
    if (t >= b) return 1.0f;
    float p = static_cast<float>(t - a) / static_cast<float>(b - a);
    float q = 1.0f - p;
    return 1.0f - q * q * q;
}

// Fade in over [inA, inB], out over [outA, outB].
lv_opa_t fade(uint32_t t, uint32_t inA, uint32_t inB, uint32_t outA, uint32_t outB) {
    float v = ease(t, inA, inB) * (1.0f - ease(t, outA, outB));
    return static_cast<lv_opa_t>(v * 255.0f + 0.5f);
}

void setOpa(lv_obj_t *img, lv_opa_t opa) {
    // Hidden outright when fully transparent, so the off-beat image costs
    // nothing to draw instead of being blended at zero.
    if (opa == LV_OPA_TRANSP) {
        lv_obj_add_flag(img, LV_OBJ_FLAG_HIDDEN);
    } else {
        lv_obj_clear_flag(img, LV_OBJ_FLAG_HIDDEN);
        lv_obj_set_style_img_opa(img, opa, 0);
    }
}

void finish() {
    if (g_timer) {
        lv_timer_del(g_timer);
        g_timer = nullptr;
    }
    if (g_overlay) {
        lv_obj_del(g_overlay);
        g_overlay = g_first = g_second = nullptr;
    }
}

void tick(lv_timer_t *) {
    uint32_t t = lv_tick_elaps(g_startMs);
    if (t >= kSecondOutEnd) {
        finish();
        return;
    }
    setOpa(g_first, fade(t, kFirstInStart, kFirstInEnd, kFirstOutStart, kFirstOutEnd));
    setOpa(g_second, fade(t, kSecondInStart, kSecondInEnd, kSecondOutStart, kSecondOutEnd));
}

lv_obj_t *makeImage(const lv_img_dsc_t *src) {
    lv_obj_t *img = lv_img_create(g_overlay);
    lv_img_set_src(img, src);
    lv_obj_center(img);
    lv_obj_add_flag(img, LV_OBJ_FLAG_HIDDEN);
    return img;
}
} // namespace

void build(lv_obj_t *parent) {
    g_overlay = lv_obj_create(parent);
    lv_obj_remove_style_all(g_overlay);
    lv_obj_set_size(g_overlay, LV_PCT(100), LV_PCT(100));
    lv_obj_set_style_bg_color(g_overlay, Colors::kBg, 0);
    lv_obj_set_style_bg_opa(g_overlay, LV_OPA_COVER, 0);
    lv_obj_clear_flag(g_overlay, LV_OBJ_FLAG_SCROLLABLE | LV_OBJ_FLAG_CLICKABLE);

    g_first = makeImage(&boot_img_toyota);
    g_second = makeImage(&boot_img_gr_yaris);

    g_startMs = lv_tick_get();
    g_timer = lv_timer_create(tick, 20, nullptr);
}

bool active() { return g_overlay != nullptr; }

void skip() { finish(); }

} // namespace BootUi
